"package com.example.app.configuration.port;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;

public record ActiveReferenceTableSnapshot(
        UUID tableId,
        String tableCode,
        String displayName,
        UUID activeVersionId,
        int versionNumber,
        String lifecycleStatus,
        List<String> columns,
        Map<String, Map<String, String>> rowsByKey,
        int rowCount,
        Instant effectiveAt
) {

    public ActiveReferenceTableSnapshot {
        Objects.requireNonNull(tableId, "tableId must not be null");
        Objects.requireNonNull(tableCode, "tableCode must not be null");
        Objects.requireNonNull(displayName, "displayName must not be null");
        Objects.requireNonNull(activeVersionId, "activeVersionId must not be null");
        Objects.requireNonNull(lifecycleStatus, "lifecycleStatus must not be null");
        columns = columns == null ? List.of() : List.copyOf(columns);
        rowsByKey = copyRowsByKey(rowsByKey);
    }

    private static Map<String, Map<String, String>> copyRowsByKey(
            Map<String, Map<String, String>> source) {
        if (source == null || source.isEmpty()) {
            return Map.of();
        }
        Map<String, Map<String, String>> copy = new LinkedHashMap<>();
        for (Map.Entry<String, Map<String, String>> entry : source.entrySet()) {
            Map<String, String> inner = entry.getValue() == null
                    ? Map.of()
                    : Map.copyOf(entry.getValue());
            copy.put(entry.getKey(), inner);
        }
        return Collections.unmodifiableMap(copy);
    }
}
