public record ReferenceTableRowDto(
        UUID id,
        int rowIndex,
        String rowKey,
        Map<String, String> rowValuesJson
) {

    public ReferenceTableRowDto {
        rowValuesJson = rowValuesJson == null ? Map.of() : Map.copyOf(rowValuesJson);
